ottom: 8px; } .stat-card { background: var(--gray-50); border-radius: var(--radius); padding: 20px; display: flex; align-items: center; gap: 14px; } .stat-icon { width: 48px; height: 48px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 22px; flex-shrink: 0; } .stat-icon-send { background: #E6FAF8; } .stat-icon-week { background: #E6FAF8; } .stat-icon-month { background: #E6FAF8; } .stat-icon-cost { background: #FFE4E6; } .stat-label { font-size: 12px; color: var(--gray-500); margin-bottom: 2px; } .stat-value { font-size: 20px; font-weight: 700; color: var(--gray-900); } /* ─── Quick Send ─── */ .quick-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; } .quick-item { border: 1px solid var(--gray-200); border-radius: var(--radius-sm); padding: 16px 20px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; cursor: pointer; transition: all 0.2s; background: white; } .quick-item:hover { border-color: var(--primary); background: var(--primary); } .quick-item:hover .quick-label { color: white; } .quick-item:hover .quick-icon { color: white; } .quick-icon { font-size: 18px; color: var(--primary); } .quick-label { font-size: 13px; font-weight: 600; color: var(--gray-700); text-align: center; } /* ─── Resident SMS Section ─── */ .resident-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; } .resident-controls { display: flex; gap: 10px; align-items: center; } .select-input, .search-input { padding: 7px 12px; border: 1px solid var(--gray-200); border-radius: var(--radius-sm); font-size: 13px; font-family: 'Noto Sans KR', sans-serif; color: var(--gray-700); background: white; outline: none; } .select-input:focus, .search-input:focus { border-color: var(--primary); } .search-input { width: 180px; } .resident-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; } .resident-card { border: 1px solid var(--gra