tle">발송 미리보기</div> <button class="msg-modal-close" onclick="closePreviewModal()"> ✕ </button> </div> <div class="msg-modal-body" style="flex:1; overflow-y:auto; display:flex; flex-direction:column; gap:16px;"> <!-- 수신자 --> <div style="display:flex; align-items:flex-start; gap:12px; padding:14px 16px; border:1px solid var(--gray-200); border-radius:var(--radius-sm);"> <span style="font-size:13px; color:var(--gray-500); flex-shrink:0; width:60px;">수신자</span> <span id="preview-recipient" style="font-size:13px; color:var(--gray-900); font-weight:600;"></span> </div> <!-- 발송 유형 --> <div id="preview-schedule-row" style="display:flex; align-items:flex-start; gap:12px; padding:14px 16px; border:1px solid var(--gray-200); border-radius:var(--radius-sm);"> <span style="font-size:13px; color:var(--gray-500); flex-shrink:0; width:60px;" id="preview-schedule-label">발송 일시</span> <span id="preview-schedule-val" style="font-size:13px; color:var(--gray-900); font-weight:600;"></span> </div> <!-- 메시지 내용 --> <div> <div style="font-size:13px; font-weight:600; color:var(--gray-700); margin-bottom:8px;">메시지 내용</div> <div style="background:var(--gray-50); border-radius:var(--radius-sm); padding:16px; display:flex; justify-content:flex-end;"> <div style="max-width:80%; background:#1ECEC0; color:white; border-radius:16px 16px 4px 16px; padding:12px 16px; font-size:13px; line-height:1.6; white-space:pre-wrap; word-break:break-all;" id="preview-content"></div> </div> <div style="text-align:right; font-size:12px; color:var(--gray-400); margin-top:6px;"><span id="preview-char"></span>자</div> </div> <!-- 예상 비용 --> <div id="preview-cost-box" style="display:flex; align-items:center; justify-content:space-between; padding:14px 16px; background:var(--primary-bg); border:1px solid #99e8e2; border-radius:var(--radius-sm);"> <div style="display:flex; align-items:center; gap:8px;"> <span id="preview-cost-type" style="font-size:12px; font-weight:700; padding:3px 10px; border-radius:20px; background:#dbea