<script>
/*  ── 템플릿 관리 모달 ── */ const typeMap = { unpaid: { label:'결제', cls:'msg-badge-warning' }, facility: { label:'시설', cls:'', style:'background:#dbeafe;color:#1e40af;' }, notice: { label:'공지', cls:'', style:'background:#d1fae5;color:#065f46;' }, checkinout: { label:'입퇴실', cls:'', style:'background:#ede9fe;color:#6d28d9;' }, general: { label:'일반', cls:'', style:'background:#f3f4f6;color:#374151;' }, }; let tplData = [ { id:1, title:'미납 안내', type:'unpaid', content:'안녕하세요, {이름} 님. \n{호실번호} 호 입실료 {미납금액} 원이 아직 납부되지 않았습니다. \n 납부일은 {납부일} 까지입니다. \n 확인 후 납부 부탁드립니다.', isFavorite:true }, { id:2, title:'시설 점검 안내', type:'facility', content:'내일 오전 10 시부터 시설 점검이 있습니다. 불편을 드려 죄송합니다. 협조 부탁드립니다.', isFavorite:true }, { id:3, title:'긴급 공지', type:'notice', content:'긴급 공지입니다. 즉시 확인 부탁드립니다. 관리사무소로 연락 바랍니다.', isFavorite:true }, { id:4, title:'공지사항', type:'notice', content:'공지사항이 있어 알려드립니다. 자세한 내용은 관리사무소로 문의해주세요.', isFavorite:true }, { id:5, title:'입실 안내', type:'checkinout', content:'안녕하세요, {이름} 님. \n{호실번호} 호 입실을 환영합니다. \n 입실 관련 안내 사항은 관리사무소에서 확인하실 수 있습니다. \n 편안한 생활이 되시길 바랍니다.', isFavorite:false }, { id:6, title:'퇴실 안내', type:'checkinout', content:'안녕하세요, {이름} 님. \n{호실번호} 호 퇴실 처리가 완료되었습니다. \n 퇴실 관련 정산 및 보증금 반환은 관리사무소로 문의해주세요. \n 그동안 이용해 주셔서 감사합니다 .', isFavorite:false }, ]; let tplNextId = 7; let tplEditId = null; function renderFavorites() { const grid = document.getElementById('favorite-grid'); if (!grid) return; const favs = tplData.filter(t => t.isFavorite); if (!favs.length) { grid.innerHTML = '<div style="color:var(--gray-400); font-size:13px; padding:8px 0;">즐겨찾기된 템플릿이 없습니다 .</ div>'; return; } grid.innerHTML = favs.map(t => { const tm = typeMap[t.type] || { label:'기타', cls:'', style:'' }; const badgeStyle = tm.style ? `style="${tm.style}"` : ''; return `<div class="template-card"> <div class="template-card-header"> <span class="template-name">${t.title}</span> <span class="msg-badge ${tm.cls}" ${badgeStyle}>${tm.label}</span> </div> <div class="template-body-wrap"><div class="template-body">${t.content}</div></div> <div class="template-actions"> <button class="msg-btn msg-btn-secondary msg-btn-sm" onclick="openTemplateModalEdit(${t.id})">수정</ button> </div> </div>`; }).join(''); } function toggleGroupFavorite(type) { const group = tplData.filter(t => t.type === type); const allFav = group.every(t => t.isFavorite); group.forEach(t => { t.isFavorite = !allFav; }); renderTplList(); renderFavorites(); } function toggleFavorite(id) { const t = tplData.find(x => x.id === id); if (t) { t.isFavorite = !t.isFavorite; renderTplList(); renderFavorites(); } } function removeFavorite(id) { const t = tplData.find(x => x.id === id); if (t) { t.isFavorite = false; renderFavorites(); } } function openFavoritePicker() { const nonFavs = tplData.filter(t => !t.isFavorite); const list = document.getElementById('fav-picker-list'); if (!nonFavs.length) { list.innerHTML = '<div style="padding:20px; text-align:center; color:var(--gray-400); font-size:13px;">추가할 수 있는 템플릿이 없습니다 .</ div>'; } else { list.innerHTML = nonFavs.map(t => { const tm = typeMap[t.type] || { label:'기타', cls:'', style:'' }; const badgeStyle = tm.style ? `style="${tm.style}"` : ''; return `<div style="display:flex; align-items:center; gap:12px; padding:12px 20px; border-bottom:1px solid var(--gray-100); cursor:pointer;" onclick="addFavorite(${t.id})"> <div style="flex:1; min-width:0;"> <div style="display:flex; align-items:center; gap:8px; margin-bottom:4px;"> <span class="msg-badge ${tm.cls}" ${badgeStyle}>${tm.label}</span> <span style="font-size:14px; font-weight:600; color:var(--gray-900);">${t.title}</span> </div> <div style="font-size:12px; color:var(--gray-400); overflow:hidden; white-space:nowrap; text-overflow:ellipsis;">${t.content}</div> </div> <button class="msg-btn msg-btn-primary msg-btn-sm" onclick="event.stopPropagation(); addFavorite(${t.id})">추가</ button> </div>`; }).join(''); } document.getElementById('favPickerModal').classList.add('open'); document.body.style.overflow = 'hidden'; } function addFavorite(id) { const t = tplData.find(x => x.id === id); if (t) { t.isFavorite = true; renderFavorites(); closeFavPicker(); } } function closeFavPicker(e) { if (e && e.target !== document.getElementById('favPickerModal')) return; document.getElementById('favPickerModal').classList.remove('open'); document.body.style.overflow = ''; } function openTemplateModalEdit(id) { document.getElementById('templateModal').classList.add('open'); showTplForm(id); } function openTemplateModal() { showTplList(); document.getElementById('templateModal').classList.add('open'); } function closeTemplateModal(e) { if (e && e.target !== document.getElementById('templateModal')) return; document.getElementById('templateModal').classList.remove('open'); } function showTplList() { document.getElementById('tpl-modal-title').textContent = '문자 템플릿 관리'; document.getElementById('tpl-toolbar').style.display = 'flex'; document.getElementById('tpl-list-view').style.display = ''; document.getElementById('tpl-form-view').style.display = 'none'; renderTplList(); } let tplPage = 1; let tplPerPage = 10; function renderTplList() { const inner = document.getElementById('tpl-list-inner'); const query = (document.getElementById('tpl-search')?.value || '').trim().toLowerCase(); const filterType = document.getElementById('tpl-filter')?.value || ''; const filtered = tplData.filter(t => (!filterType || t.type === filterType) && (!query || t.title.toLowerCase().includes(query) || t.content.toLowerCase().includes(query)) ); if (!filtered.length) { inner.innerHTML = '<div style="padding:40px; text-align:center; color:var(--gray-400); font-size:14px;">등록된 템플릿이 없습니다 .</ div>'; document.getElementById('tpl-pag-info').textContent = '0건'; document.getElementById('tpl-pag-pages').innerHTML = ''; document.getElementById('tpl-per-page-wrap').style.display = 'none'; return; } /*  페이지네이션 */ const total = filtered.length; const totalPages = Math.max(1, Math.ceil(total / tplPerPage)); if (tplPage > totalPages) tplPage = totalPages; const start = (tplPage - 1) * tplPerPage; const pageItems = filtered.slice(start, start + tplPerPage); /*  카테고리 그룹 순서 */ const groupOrder = ['unpaid','facility','notice','checkinout','general']; const groupLabel = { unpaid: '결제', facility: '시설', notice: '공지', checkinout: '입퇴실', general: '일반' }; /*  그룹별 분류 ( 페이지 항목 기준 ) */ const groups = {}; pageItems.forEach(t => { if (!groups[t.type]) groups[t.type] = []; groups[t.type].push(t); }); let html = ''; groupOrder.forEach(type => { if (!groups[type]) return; const tm = typeMap[type]; const badgeStyle = tm.style ? `style="${tm.style}"` : ''; html += `<div style="padding:10px 20px; background:var(--gray-50); border-bottom:1px solid var(--gray-200); display:flex; align-items:center; gap:8px;"> <span class="msg-badge ${tm.cls}" ${badgeStyle}>${groupLabel[type]}</span> </div>`; groups[type].forEach(t => { const starColor = t.isFavorite ? '#f59e0b' : '#d1d5db'; html += ` <div style="display:flex; align-items:flex-start; gap:12px; padding:14px 20px 14px 32px; border-bottom:1px solid var(--gray-100);"> <div style="flex:1; min-width:0;"> <div style="display:flex; align-items:center; gap:6px; margin-bottom:4px;"> <span style="font-size:14px; font-weight:600; color:var(--gray-900);">${t.title}</span> <button onclick="toggleFavorite(${t.id})" style="background:none; border:none; cursor:pointer; font-size:15px; color:${starColor}; line-height:1; padding:0; flex-shrink:0;" title=" 즐겨찾기 "> ★ </ button> </div> <div style="font-size:13px; color:var(--gray-500); line-height:1.5; overflow:hidden; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical;">${t.content}</div> </div> <div style="display:flex; align-items:center; gap:6px; flex-shrink:0; padding-top:2px;"> <button class="msg-btn msg-btn-secondary msg-btn-sm" onclick="showTplForm(${t.id})">수정</ button> <button class="msg-btn msg-btn-danger msg-btn-sm" onclick="deleteTpl(${t.id})">삭제</ button> </div> </div>`; }); }); /*  기타 타입 */ const others = pageItems.filter(t => !groupOrder.includes(t.type)); if (others.length) { html += `<div style="padding:10px 20px; background:var(--gray-50); border-bottom:1px solid var(--gray-200);">기타</ div>`; others.forEach(t => { html += ` <div style="display:flex; align-items:flex-start; gap:12px; padding:14px 20px 14px 32px; border-bottom:1px solid var(--gray-100);"> <div style="flex:1; min-width:0;"> <div style="font-size:14px; font-weight:600; color:var(--gray-900); margin-bottom:4px;">${t.title}</div> <div style="font-size:13px; color:var(--gray-500); line-height:1.5;">${t.content}</div> </div> <div style="display:flex; align-items:center; gap:6px; flex-shrink:0;"> <button class="msg-btn msg-btn-secondary msg-btn-sm" onclick="showTplForm(${t.id})">수정</ button> <button class="msg-btn msg-btn-danger msg-btn-sm" onclick="deleteTpl(${t.id})">삭제</ button> </div> </div>`; }); } inner.innerHTML = html; const from = total ? start + 1 : 0; const to = Math.min(start + tplPerPage, total); document.getElementById('tpl-pag-info').textContent = `${total} 건 중 ${from} 건부터 ${to} 건까지 보기 `; document.getElementById('tpl-per-page-wrap').style.display = ''; renderPageBtns('tpl-pag-pages', tplPage, totalPages, tplGoPage); renderFavorites(); } function tplGoPage(p) { tplPage = p; renderTplList(); } function showTplForm(id) { tplEditId = id; document.getElementById('tpl-modal-title').textContent = id ? '템플릿 수정' : '템플릿 추가'; document.getElementById('tpl-toolbar').style.display = 'none'; document.querySelector('#templateModal .msg-modal-header').style.paddingBottom = '4px'; document.getElementById('tpl-list-view').style.display = 'none'; document.getElementById('tpl-form-view').style.display = ''; if (id) { const t = tplData.find(x => x.id === id); document.getElementById('tpl-title').value = t.title; document.getElementById('tpl-type').value = t.type; document.getElementById('tpl-content').value = t.content; document.getElementById('tpl-count').textContent = t.content.length; } else { document.getElementById('tpl-title').value = ''; document.getElementById('tpl-type').value = ''; document.getElementById('tpl-content').value = ''; document.getElementById('tpl-count').textContent = '0'; } document.getElementById('tpl-title-err').style.display = 'none'; document.getElementById('tpl-title').style.borderColor = '#e5e7eb'; document.getElementById('tpl-type-err').style.display = 'none'; document.getElementById('tpl-type').style.borderColor = '#e5e7eb'; document.getElementById('tpl-content-err').style.display = 'none'; document.getElementById('tpl-content').style.borderColor = '#e5e7eb'; const tplVarToggle = document.getElementById('tpl-var-toggle'); if (tplVarToggle) { tplVarToggle.checked = false; document.getElementById('tpl-var-buttons').style.display = 'none'; } } function saveTplForm() { const title = document.getElementById('tpl-title').value.trim(); const type = document.getElementById('tpl-type').value; const content = document.getElementById('tpl-content').value.trim(); let hasErr = false; if (!title) { document.getElementById('tpl-title-err').style.display = 'block'; document.getElementById('tpl-title').style.borderColor = '#ef4444'; hasErr = true; } if (!type) { document.getElementById('tpl-type-err').style.display = 'block'; document.getElementById('tpl-type').style.borderColor = '#ef4444'; hasErr = true; } if (!content) { document.getElementById('tpl-content-err').style.display = 'block'; document.getElementById('tpl-content').style.borderColor = '#ef4444'; hasErr = true; } if (hasErr) return; if (tplEditId) { const t = tplData.find(x => x.id === tplEditId); t.title = title; t.type = type; t.content = content; } else { tplData.push({ id: tplNextId++, title, type, content }); } showTplList(); } function deleteTpl(id) { tplData = tplData.filter(x => x.id !== id); if (tplPage > Math.max(1, Math.ceil(tplData.length / tplPerPage))) tplPage = 1; renderTplList(); } function insertTplVariable(variable) { const ta = document.getElementById('tpl-content'); const start = ta.selectionStart; const end = ta.selectionEnd; const text = ta.value; ta.value = text.substring(0, start) + `{${variable}}` + text.substring(end); ta.focus(); const cursor = start + variable.length + 2; ta.setSelectionRange(cursor, cursor); updateTplCount(); } function updateTplCount() { const val = document.getElementById('tpl-content').value; if (val.length > 1000) document.getElementById('tpl-content').value = val.slice(0, 1000); document.getElementById('tpl-count').textContent = Math.min(val.length, 1000); } /*  ── 발송 내역 모달 ── */ let historyData = @json($this->residentHistory); let hmData = []; let hmPage = 1; function openHistoryModal(name, room) { const parseDate = r => { const d = r.date.replace(/\s/g, '').replace(/\./g, '/').replace(/\/$/, ''); const isPM = r.time.startsWith('오후'); const t = r.time.replace('오전', '').replace('오후', ''); const [h, m, s] = t.split(':').map(Number); const hour = isPM && h < 12 ? h + 12 : h; return new Date(`${d} ${String(hour).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`); }; hmData = historyData .filter(r => r.name === name && r.room === room) .sort((a, b) => parseDate(b) - parseDate(a)); document.getElementById('history-modal-title').textContent = `${name} 문자 발송 내역 `; document.getElementById('history-modal-sub').textContent = `${room} • 총 ${hmData.length} 건 `; document.getElementById('hm-per-page').value = '10'; document.getElementById('hm-list-view').style.display = ''; document.getElementById('hm-detail-view').style.display = 'none'; /*  필터 초기화 */ ['hm-period-filter','hm-type-filter','hm-search','hm-date-from','hm- date-to'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; }); const dp = document.getElementById('hm-date-picker'); if (dp) dp.style.display = 'none'; hmPaginate(1); document.getElementById('historyModal').classList.add('open'); document.body.style.overflow = 'hidden'; } function hmToggleDatePicker() { const val = document.getElementById('hm-period-filter').value; const picker = document.getElementById('hm-date-picker'); picker.style.display = val === 'custom' ? 'flex' : 'none'; if (val !== 'custom') { document.getElementById('hm-date-from').value = ''; document.getElementById('hm-date-to').value = ''; } } function hmPaginate(page) { const perPage = parseInt(document.getElementById('hm-per-page').value); const period = document.getElementById('hm-period-filter')?.value || ''; const typeFilter = document.getElementById('hm-type-filter')?.value || ''; const query = (document.getElementById('hm-search')?.value || '').trim().toLowerCase(); const dateFrom = document.getElementById('hm-date-from')?.value || ''; const dateTo = document.getElementById('hm-date-to')?.value || ''; const toMs = r => { const d = r.date.replace(/\s/g,'').replace(/\./g,'/').replace(/\/$/,''); const isPM = r.time.startsWith('오후'); const t = r.time.replace('오전','').replace('오후',''); const [h,m,s] = t.split(':').map(Number); return new Date(`${d} ${isPM&&h<12?h+12:h}:${m}:${s}`).getTime(); }; const now = new Date(); const startOfDay = d => { const x=new Date(d); x.setHours(0,0,0,0); return x.getTime(); }; const todayStart = startOfDay(now); const weekStart = startOfDay(new Date(now.getFullYear(), now.getMonth(), now.getDate() - now.getDay())); const monthStart = startOfDay(new Date(now.getFullYear(), now.getMonth(), 1)); const filtered = hmData.filter(r => { const ms = toMs(r); let matchPeriod = true; if (period === 'today') matchPeriod = ms >= todayStart; else if (period === 'week') matchPeriod = ms >= weekStart; else if (period === 'month') matchPeriod = ms >= monthStart; else if (period === 'custom') { if (dateFrom) matchPeriod = matchPeriod && ms >= startOfDay(new Date(dateFrom)); if (dateTo) matchPeriod = matchPeriod && ms <= startOfDay(new Date(dateTo)) + 86399999; } const matchType = !typeFilter || r.type === typeFilter; const matchQ = !query || [r.type, r.status, r.content, r.date].join(' ').toLowerCase().includes(query); return matchPeriod && matchType && matchQ; }); const total = filtered.length; const totalPages = Math.ceil(total / perPage) || 1; hmPage = Math.max(1, Math.min(page, totalPages)); const start = (hmPage - 1) * perPage; const end = start + perPage; const list = document.getElementById('history-modal-list'); if (total === 0) { list.innerHTML = `<div class="history-modal-empty">발송 내역이 없습니다 .</ div>`; document.getElementById('hm-info').textContent = '0건'; } else { list.innerHTML = filtered.slice(start, end).map((r, i) => ` <div class="history-modal-item" onclick="hmShowDetail(${start + i})"> <div class="history-modal-row"> <span class="type-badge ${r.typeClass}">${r.type}</span> <span class="status-badge ${r.statusClass}">${r.status}</span> <span class="history-modal-date">${r.date} ${r.time}</span> </div> <div class="history-modal-content">${r.content}</div> </div>`).join(''); const from = start + 1, to = Math.min(end, total); document.getElementById('hm-info').textContent = `${total} 건 중 ${from} 건부터 ${to} 건까지 보기 `; } renderPageBtns('hm-pages', hmPage, totalPages, hmPaginate); } function hmShowDetail(idx) { const r = hmData[idx]; if (!r) return; const rows = [ ['발송 일시', `${r.date} ${r.time}`], ['유형', `<span class="type-badge ${r.typeClass}">${r.type}</span>`], ['상태', `<span class="status-badge ${r.statusClass}">${r.status}</span>`], ['내용', `<div style="font-size:13px; color:var(--gray-700); line-height:1.6; padding:4px 0; white-space:pre-wrap;">${r.content}</div>`], ]; document.getElementById('hm-detail-inner').innerHTML = rows.map(([label, val]) => ` <div style="display:flex; align-items:flex-start; gap:16px; padding:14px 20px; border-bottom:1px solid var(--gray-100);"> <div style="font-size:13px; color:var(--gray-500); flex-shrink:0; width:72px;">${label}</div> <div style="font-size:13px; color:var(--gray-900); flex:1;">${val}</div> </div>`).join(''); document.getElementById('hm-list-view').style.display = 'none'; document.getElementById('hm-detail-view').style.display = ''; } function hmShowList() { document.getElementById('hm-detail-view').style.display = 'none'; document.getElementById('hm-list-view').style.display = ''; } function closeHistoryModal(e) { if (e && e.target !== document.getElementById('historyModal')) return; document.getElementById('historyModal').classList.remove('open'); document.body.style.overflow = ''; } /*  ── 빠른 발송 카드 선택 ── */ function setActive(el) { document.querySelectorAll('.quick-item').forEach(i => i.classList.remove('active')); el.classList.add('active'); } /*  ── 공통 페이지 버튼 렌더링 ── */ function renderPageBtns(containerId, currentPage, totalPages, onPageClick) { const container = document.getElementById(containerId); container.innerHTML = ''; container.style.display = 'flex'; container.style.alignItems = 'center'; container.style.gap = '4px'; const prev = document.createElement('button'); prev.className = 'page-btn'; prev.textContent = '‹'; prev.disabled = currentPage === 1; prev.onclick = () => onPageClick(currentPage - 1); container.appendChild(prev); const numGroup = document.createElement('div'); numGroup.style.cssText = 'display:flex; gap:4px; margin:0 4px;'; for (let i = 1; i <= totalPages; i++) { const btn = document.createElement('button'); btn.className = 'page-btn' + (i === currentPage ? ' active' : ''); btn.textContent = i; btn.onclick = () => onPageClick(i); numGroup.appendChild(btn); } container.appendChild(numGroup); const next = document.createElement('button'); next.className = 'page-btn'; next.textContent = '›'; next.disabled = currentPage === totalPages || totalPages === 0; next.onclick = () => onPageClick(currentPage + 1); container.appendChild(next); } /*  ── 입주자 필터 ── */ const badgeMap = { paid: '정상 납부', unpaid: '미납', new: '신규 입주' }; function applyResidentFilter() { residentPaginate(1); } function getFilteredCards() { const filter = document.getElementById('resident-filter').value; const query = (document.getElementById('resident-search')?.value || '').trim().toLowerCase(); return allResidentCards.filter(card => { const cardFilter = card.dataset.filter || ''; const matchFilter = filter === 'all' || cardFilter === filter; const name = card.querySelector('.resident-name')?.textContent.toLowerCase() || ''; const room = card.querySelector('.resident-meta')?.textContent.toLowerCase() || ''; const matchSearch = !query || name.includes(query) || room.includes(query); return matchFilter && matchSearch; }); } /*  ── 입주자별 문자 관리 페이지네이션 ── */ const allResidentCards = Array.from(document.querySelectorAll('.resident-card')); const totalResidents = allResidentCards.length; let residentPage = 1; function residentPaginate(page) { const filtered = getFilteredCards(); const perPage = parseInt(document.getElementById('resident-per-page').value); const totalPages = Math.ceil(filtered.length / perPage) || 1; residentPage = Math.max(1, Math.min(page, totalPages)); const start = (residentPage - 1) * perPage; const end = start + perPage; /*  전체 숨기고 필터 + 페이지 범위만 표시 */ allResidentCards.forEach(card => card.style.display = 'none'); filtered.forEach((card, i) => { card.style.display = (i >= start && i < end) ? '' : 'none'; }); const from = filtered.length ? start + 1 : 0; const to = Math.min(end, filtered.length); document.getElementById('resident-info').textContent = `${filtered.length} 건 중 ${from} 건부터 ${to} 건까지 보기 `; renderPageBtns('resident-pages', residentPage, totalPages, residentPaginate); } /*  ── 발송 내역 페이지네이션 ── */ let historyPage = 1; function renderHistoryRow(r) { const dateStr = `${r.date}<br>${r.time}`; const detailArgs = `'${r.date} ${r.time}','${r.name}','${r.room}','${r.content.replace(/'/g,"\\'")} ','${r.type}','${r.typeClass}','${r.status}','${r.statusClass}','20원'`; return `<tr> <td class="td-date">${dateStr}</td> <td>${r.name}</td><td>${r.room}</td> <td class="td-content">${r.content}</td> <td><span class="type-badge ${r.typeClass}">${r.type}</span></td> <td><span class="status-badge ${r.statusClass}">${r.status}</span></td> <td class="td-cost">20원</ td> <td><div c