} else { const firstResident = Object.values(residentDataMapLocal)[0]; previewContent = replaceVariables(content, firstResident); } } document.getElementById('preview-content').textContent = previewContent; document.getElementById('preview-char').textContent = previewContent.length; document.getElementById('preview-confirm-btn').textContent = confirmLabel; /*  수신자 수 계산 → 예상 비용 (SMS/MMS 반영 ) */ let recipientCount = 1; if (document.getElementById('single-recipient-info').style.display !== 'none') { recipientCount = 1; } else { const checkboxes = document.querySelectorAll('#unpaid-checklist input[type="checkbox"]:checked'); if (checkboxes.length > 0) { recipientCount = checkboxes.length; } else { recipientCount = allResidentCards.length; } } const costText = getMsgCostText(currentMsgIsMMS, recipientCount); const msgTypeLabel = currentMsgIsMMS ? 'MMS' : 'SMS'; document.getElementById('preview-cost-count').textContent = recipientCount; const previewTypeBadge = document.getElementById('preview-cost-type'); previewTypeBadge.textContent = msgTypeLabel; previewTypeBadge.style.background = currentMsgIsMMS ? '#fef3c7' : '#dbeafe'; previewTypeBadge.style.color = currentMsgIsMMS ? '#92400e' : '#1e40af'; document.getElementById('preview-cost-total').textContent = costText; /*  미리보기 비용 영역 색상 MMS 여부에 따라 변경 */ const previewCostBox = document.getElementById('preview-cost-box'); if (currentMsgIsMMS) { previewCostBox.style.background = '#fffbeb'; previewCostBox.style.borderColor = '#fde68a'; document.getElementById('preview-cost-total').style.color = '#d97706'; } else { previewCostBox.style.background = 'var(--primary-bg)'; previewCostBox.style.borderColor = '#99e8e2'; document.getElementById('preview-cost-total').style.color = 'var(--primary)'; } pendingSendData = { scheduleOn, repeatOn }; document.getElementById('previewModal').classList.add('open'); 
