lass, status:'발송 완료', statusClass:'status-done', content, isBroadcast }); }); historyPaginate(1); } else { const recipientLabel = recipients.length === 1 ? `${recipients[0].name} · ${recipients[0].room}` : `${recipients[0].name} 외 ${recipients.length-1} 명 `; let datetime = ''; if (scheduleOn) { const date = document.getElementById('schedule-date').value; const time = document.getElementById('schedule-time').value; datetime = `${date} ${time}`; } else { const cycleLabel = { daily:'매일', weekly:'매주', monthly:'매월' }; const cycle = document.getElementById('repeat-cycle').value; const time = document.getElementById('repeat-time').value; const end = document.getElementById('repeat-end').value; datetime = `${cycleLabel[cycle]} ${time} (${end} 까지 )`; } const newId = scheduleItems.length ? Math.max(...scheduleItems.map(x=>x.id)) + 1 : 1; scheduleItems.unshift({ id: newId, type: scheduleOn ? 'schedule' : 'repeat', smsType: smsTypeLabel, recipient: recipientLabel, content, datetime }); } /* 발송 결과: 즉시 발송이면 백엔드에 영속화하여 하단 테이블 갱신 */
